import {agents,scenarios,seedAudit} from './data.js';
import {evaluate} from './engine.js';
import {ensureReceiptChain,verifyReceiptChain,renderReceiptLedger} from './receipts.js';

const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'◫',control:'⌁',attacks:'⌬',audit:'▤',architecture:'⌘'};
let state={page:location.hash.slice(1)||'overview',logged:sessionStorage.aegisLogin==='1',dark:localStorage.aegisTheme!=='light',sidebarCollapsed:localStorage.aegisSidebarCollapsed==='1',demo:true,agent:agents[0],action:{...scenarios[1]},evaluation:null,audit:JSON.parse(localStorage.aegisAudit||'null')||[...seedAudit],showWhy:false,showMap:false,mapHop:0,search:'',filter:'ALL',attackFilter:'ALL',archMode:'normal',archNode:'gate',qualcommStatus:'CHECKING BACKEND',qualcommOutput:'',studioScenario:'refund',studioAgent:'AGT-FIN-042',studioEnv:'Production',studioHour:2,studioFrequency:17,studioAmount:48000,studioTarget:'Unknown refund API',studioReversible:false,receiptIntegrity:'CHECKING',receiptExpanded:null,toast:''};
const nav=[['overview','Control Plane'],['studio','Trust Simulator'],['attacks','Attack Lab'],['audit','Audit Trail'],['architecture','Architecture']];
function save(){localStorage.aegisAudit=JSON.stringify(state.audit);}
async function sealReceipts(){state.receiptIntegrity=await ensureReceiptChain(state.audit);if(state.receiptIntegrity==='SEALED'){save();state.receiptIntegrity=await verifyReceiptChain(state.audit);}if(state.logged)render();}
async function verifyReceiptsNow(){state.receiptIntegrity=await verifyReceiptChain(state.audit);render();}
function statusClass(d){return d==='ALLOW'?'allow':d==='BLOCK'?'block':'review'}
function render(){document.documentElement.dataset.theme=state.dark?'dark':'light';document.body.classList.toggle('logged',state.logged);$('#app').innerHTML=state.logged?shell():login();bind();}
async function loadProviderStatus(){try{const r=await fetch('/api/qai/status');const d=await r.json();state.qualcommStatus=d.configured?'BACKEND READY':'BACKEND NOT CONFIGURED';}catch{state.qualcommStatus='BACKEND OFFLINE';}if(state.logged)render();}
function login(){return `<main class="login"><section class="login-brand"><div class="brand-mark">A</div><span class="eyebrow">AUTONOMOUS AI SAFETY & GOVERNANCE</span><h1>Think before<br><em>AI acts.</em></h1><p>Dynamic pre-execution governance for autonomous AI agents.</p><div class="login-proof"><span>AEGIS INTERCEPTS</span><b>→</b><span>AEGIS DOES NOT EXECUTE</span></div></section><form class="login-card" id="login"><div class="brandline"><span class="brand-mark small">A</span><span>AEGIS <small>GOVERNANCE CONSOLE</small></span></div><div class="eyebrow">SECURE OPERATOR ACCESS</div><h2>Welcome back</h2><p>Enter the simulation environment.</p><label>Operator email<input name="email" type="email" value="operator@aegis.demo" required autocomplete="username"></label><label>Password<input name="password" type="password" value="governance" required autocomplete="current-password"></label><button class="primary full">Sign in to AEGIS <span>→</span></button><div class="login-foot"><span class="dot green"></span> SIMULATION ENVIRONMENT <span>·</span> LOCAL DEMO</div></form></main>`}
function shell(){return `<div class="app-shell ${state.sidebarCollapsed?'sidebar-collapsed':''}"><aside class="sidebar"><div class="brandline"><span class="brand-mark small">A</span><span>AEGIS<small>TRUST CONTROL PLANE</small></span></div><div class="side-label">WORKSPACE</div><nav>${nav.map(([id,name])=>`<a href="#${id}" class="nav-item ${state.page===id?'active':''}"><span class="nav-icon">${icons[id]||'◉'}</span>${name}${id==='attacks'?'<span class="nav-count">'+(scenarios.length-1)+'</span>':''}</a>`).join('')}</nav><div class="side-bottom"><button class="text-button" id="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" id="mobile-menu" aria-label="${window.matchMedia('(max-width:800px)').matches||state.sidebarCollapsed?'Open navigation':'Close navigation'}" aria-expanded="${window.matchMedia('(max-width:800px)').matches?'false':String(!state.sidebarCollapsed)}">${window.matchMedia('(max-width:800px)').matches||state.sidebarCollapsed?'☰':'×'}</button><div class="crumb">GOVERNANCE <span>/</span> ${nav.find(x=>x[0]===state.page)?.[1].toUpperCase()||'CONTROL PLANE'}</div><div class="top-actions"><span class="demo-tag"><i class="dot green"></i> SIMULATION ENVIRONMENT</span><button class="theme" id="theme" aria-label="Toggle theme">${state.dark?'☼':'☾'} <span>${state.dark?'Dark':'Light'}</span></button><button class="operator"><span class="avatar">RI</span><span>R. Iyer<small>SECURITY OPERATOR</small></span><b>⌄</b></button></div></header><div class="content">${state.page==='overview'?overview():state.page==='studio'?studio():state.page==='attacks'?attacks():state.page==='audit'?auditPage():architecture()}</div></main>${state.toast?`<div class="toast">${esc(state.toast)}</div>`:''}${state.showMap?mapModal():''}</div>`}
function overview(){const e=state.evaluation,a=state.action;return `<div class="page-head"><div><div class="eyebrow">PRE-EXECUTION GOVERNANCE / LIVE</div><h1>Control Plane</h1><p>Evaluate agent actions before execution.</p></div><div class="head-actions"><span class="live-pill"><i class="dot green"></i> POLICY ENGINE ACTIVE</span></div></div><div class="kpis"><div class="kpi"><span>INTERCEPTED TODAY</span><b>${state.audit.length+128}</b><small>+12% vs yesterday</small><i>↗</i></div><div class="kpi"><span>HUMAN REVIEWS</span><b>${state.audit.filter(x=>x.decision==='REVIEW').length+7}</b><small>3 awaiting decision</small><i>◷</i></div><div class="kpi"><span>BLOCKED ACTIONS</span><b>${state.audit.filter(x=>x.decision==='BLOCK').length+11}</b><small>All threats contained</small><i>⊘</i></div><div class="kpi"><span>AVG EVALUATION</span><b>18<small>ms</small></b><small>Local deterministic engine</small><i>⌁</i></div></div><div class="workspace-grid"><section class="panel composer"><div class="panel-title"><div><span class="step-no">01</span><h2>Action evaluation</h2></div><span class="eyebrow">INTERCEPTED BEFORE EXECUTION</span></div><div class="field-row"><label>AGENT IDENTITY<select id="agent">${agents.map(x=>`<option value="${x.id}" ${x.id===state.agent.id?'selected':''}>${esc(x.name)} · ${x.id}</option>`).join('')}</select></label><label>TARGET ENVIRONMENT<select id="environment"><option ${a.env==='Production'?'selected':''}>Production</option><option ${a.env==='Staging'?'selected':''}>Staging</option><option ${a.env==='Development'?'selected':''}>Development</option></select></label></div><label class="action-label">PROPOSED ACTION<textarea id="action" rows="3" placeholder="Describe the agent action to evaluate...">${esc(a.action||'')}</textarea></label><div class="scenario-row"><span>LOAD SCENARIO</span>${scenarios.slice(0,5).map(s=>`<button class="chip ${s.id===a.id?'selected':''}" data-scenario="${s.id}">${esc(s.label)}</button>`).join('')}</div><div class="eval-bottom"><div class="assurance"><span class="dot green"></span> No external AI required <span class="divider">·</span> PII patterns masked</div><button class="primary" id="evaluate">EVALUATE ACTION <span>→</span></button></div>${e?evaluationResult(e):`<div class="empty-eval"><div class="empty-orbit">⌁</div><b>Ready to evaluate</b><span>Select a scenario or enter an action to begin.</span></div>`}</section><section class="panel agent-card"><div class="panel-title"><div><span class="step-no">02</span><h2>Agent passport</h2></div><button class="icon-button" title="Agent details">↗</button></div><div class="agent-identity"><div class="agent-avatar">${state.agent.name.slice(0,1)}</div><div><h3>${esc(state.agent.name)}</h3><span>${state.agent.id} <i class="dot green"></i> VERIFIED</span><small>${esc(state.agent.role)}</small></div></div><div class="trust-summary"><div><span>BASELINE TRUST</span><b>${state.agent.trust}<small>/100</small></b></div><div class="trust-track"><i style="width:${state.agent.trust}%"></i></div></div><div class="budget"><div><b>SAFETY BUDGET</b><span>₹${(state.agent.used/1000).toFixed(0)}K / ₹${state.agent.budget/1000}K</span></div><div class="budget-track"><i style="width:${Math.min(100,state.agent.used/state.agent.budget*100)}%"></i></div><small>₹${((state.agent.budget-state.agent.used)/1000).toFixed(0)}K remaining today</small></div><div class="baseline"><div class="eyebrow">BEHAVIOURAL BASELINE</div><div class="baseline-grid"><span>Typical transaction</span><b>${state.agent.range}</b><span>Normal operating hours</span><b>${state.agent.hours}</b><span>Action frequency</span><b>${state.agent.rate}</b><span>Known targets</span><b>${state.agent.target}</b></div></div><button class="outline full" id="passport">VIEW FULL PASSPORT <span>↗</span></button></section></div>${e?extraEvaluation(e):''}${decisionExplainer(e)}<section class="panel recent"><div class="panel-title"><div><span class="step-no">03</span><h2>Recent governance events</h2></div><a href="#audit" class="link-button">VIEW AUDIT TRAIL →</a></div>${auditRows(state.audit.slice(0,4))}</section>`}
function evaluationResult(e){return `<div class="result"><div class="pipeline"><div class="pipeline-head"><span class="eyebrow">EVALUATION PIPELINE</span><span class="done"><i class="dot green"></i> COMPLETE · ${e.latency} MS</span></div><div class="stages">${[['IDENTITY','PASS'],['GUARDRAILS',e.critical?'FAIL':'PASS'],['BEHAVIOUR',e.vector.behaviour>60?'DEVIATION':'PASS'],['ACTION TWIN','READY']].map(([n,s],i)=>`<div class="stage"><span class="stage-icon ${s==='FAIL'?'red':s==='DEVIATION'?'amber':'green'}">${s==='FAIL'?'×':s==='DEVIATION'?'!':'✓'}</span><span>${n}</span><small>${s}</small></div>${i<3?'<i class="stage-line"></i>':''}`).join('')}</div></div><div class="decision ${statusClass(e.decision)}"><div class="decision-main"><div><span class="eyebrow">DYNAMIC TRUST DECISION</span><h2>${e.decision==='REVIEW'?'HUMAN REVIEW REQUIRED':e.decision==='BLOCK'?'ACTION BLOCKED':'ACTION ALLOWED'}</h2><p>${e.critical?'Critical security violation detected. Execution prevented.':e.decision==='REVIEW'?'Authorization is valid. Current behaviour and context require human authorization.':e.decision==='BLOCK'?'Risk threshold exceeded. Action prevented before execution.':'Policy, behaviour and context checks passed.'}</p></div><div class="score"><div class="score-ring" style="--score:${e.trust}"><b>${e.trust}</b></div><span>DYNAMIC<br>TRUST</span></div></div><div class="decision-actions"><button class="text-button" id="why">${state.showWhy?'HIDE EXPLANATION':'WHY THIS DECISION?'} <span>⌄</span></button><button class="text-button" id="map">WHAT WOULD HAVE HAPPENED? <span>↗</span></button><div class="decision-ctas">${e.decision==='REVIEW'?'<button class="outline" id="reject">REJECT ACTION</button><button class="primary" id="approve">APPROVE ACTION</button>':e.decision==='BLOCK'?'<button class="outline" id="sanitize">SANITIZE & RE-RUN</button>':'<span class="allow-note"><i class="dot green"></i> Ready for upstream authorization</span>'}</div></div>${state.showWhy?`<div class="reasons"><div><span>RISK VECTOR</span><b>5-DIMENSION ASSESSMENT</b></div><div class="vector-grid">${Object.entries(e.vector).map(([k,v])=>`<div class="vector"><div><span>${k.toUpperCase()} RISK</span><b>${v}<small>/100</small></b></div><div class="vector-track"><i style="width:${v}%"></i></div></div>`).join('')}</div><div class="reason-list">${e.reasons.length?e.reasons.map(r=>`<div><span class="reason-dot">+</span><span>${esc(r.label)}</span><span>${esc(r.category)}</span><b>+${r.points}</b></div>`).join(''):'<div><span class="reason-dot good">✓</span><span>All deterministic checks passed</span><span>Policy</span><b>0</b></div>'}</div><div class="total-risk"><span>AGGREGATE RISK</span><b>${e.risk}<small>/100</small></b></div></div>`:''}</div></div>`}
function extraEvaluation(e){return `<div class="detail-grid"><section class="panel dna"><div class="panel-title"><div><span class="step-no">04</span><h2>Action DNA</h2></div><span class="tag">TWIN GENERATED</span></div><div class="dna-grid">${Object.entries(e.actionDNA).map(([k,v])=>`<div><span>${k.replace(/[A-Z]/g,c=>' '+c).toUpperCase()}</span><b>${esc(v)}</b></div>`).join('')}</div></section><section class="panel impact"><div class="panel-title"><div><span class="step-no">05</span><h2>Consequence preview</h2></div><button class="text-button" id="map2">EXPAND MAP ↗</button></div><div class="impact-content"><div class="blast"><div class="blast-ring" style="--blast:${e.blast}"><b>${e.blast}</b></div><span>BLAST RADIUS<br>INDEX</span></div><div class="chain"><span>${state.agent.name}</span><i>↓</i><span class="gate">AEGIS DECISION GATE</span><i>↓</i><span class="${e.decision==='BLOCK'?'stopped':''}">${e.actionDNA.target}</span></div></div><p class="sim-note">SIMULATED CONSEQUENCE · No external action performed.</p></section></div>`}
function studioContext(){const s=scenarios.find(x=>x.id===state.studioScenario)||scenarios[1];return {...s,agent:state.studioAgent,env:state.studioEnv,hour:Number(state.studioHour),frequency:Number(state.studioFrequency),amount:Number(state.studioAmount),target:state.studioTarget,reversible:state.studioReversible,timeLabel:`${String(state.studioHour).padStart(2,'0')}:00`}}
function studioCurve(){const s=studioContext(),a=agents.find(x=>x.id===state.studioAgent)||agents[0],max=150000;let vals=Array.from({length:7},(_,i)=>evaluate({...s,amount:Math.round(max*i/6)},a).trust);let points=vals.map((v,i)=>`${54+i*122},${35+(100-v)*1.9}`).join(' ');let currentX=54+(Math.min(max,s.amount)/max)*732,currentY=35+(100*1.9)-evaluate(s,a).trust*1.9;return `<svg viewBox="0 0 840 270" class="sensitivity-chart" role="img" aria-label="Trust score sensitivity to requested amount"><line x1="54" y1="82.5" x2="786" y2="82.5" class="threshold-allow"/><line x1="54" y1="149" x2="786" y2="149" class="threshold-review"/><text x="8" y="43">100</text><text x="20" y="88">75</text><text x="20" y="155">40</text><text x="28" y="225">0</text><text x="57" y="254">₹0</text><text x="720" y="254">₹1.5L</text><text x="792" y="85" class="curve-label">ALLOW</text><text x="792" y="152" class="curve-label">REVIEW</text><polyline points="${points}" class="curve-line"/>${vals.map((v,i)=>`<circle cx="${54+i*122}" cy="${35+(100-v)*1.9}" r="3.5"><title>₹${(max*i/6).toLocaleString('en-IN')} request · trust ${v}</title></circle>`).join('')}<line x1="${currentX}" y1="32" x2="${currentX}" y2="225" class="current-marker"/><circle cx="${currentX}" cy="${currentY}" r="7" class="current-point"><title>Current variant · trust ${evaluate(s,a).trust}</title></circle></svg>`}
function studioResults(){const s=studioContext(),agent=agents.find(x=>x.id===state.studioAgent)||agents[0],base=scenarios.find(x=>x.id===state.studioScenario)||scenarios[1],baseAgent=agents.find(x=>x.id===base.agent)||agents[0],current=evaluate(s,agent),baseline=evaluate(base,baseAgent),delta=current.trust-baseline.trust,checks=[['Agent trust',agent.trust],['Environment',s.env==='Production'?28:8],['Time deviation',s.hour<7||s.hour>=21?90:15],['Burst rate',Math.min(100,Math.round(s.frequency/20*100))],['Destination',/unknown|external|unverified/i.test(s.target)?88:12],['Reversibility',s.reversible?10:88]];return `<div class="studio-live"><div class="studio-decision ${statusClass(current.decision)}"><div class="studio-score"><div class="score-ring" style="--score:${current.trust}"><b>${current.trust}</b></div><span>DYNAMIC<br>TRUST</span></div><div class="studio-outcome"><span class="eyebrow">LIVE WHAT-IF DECISION</span><h2>${current.decision==='REVIEW'?'HUMAN REVIEW REQUIRED':current.decision==='BLOCK'?'ACTION BLOCKED':'ACTION ALLOWED'}</h2><p>${current.critical?'Critical override matched.':current.decision==='REVIEW'?'This context needs a human authorization.':current.decision==='BLOCK'?'A hard policy or budget boundary was crossed.':'This agent and context clear the current policy.'}</p></div><div class="delta ${delta>=0?'positive':'negative'}"><b>${delta>=0?'+':''}${delta}</b><span>TRUST CHANGE<br>VS BASELINE</span></div></div><div class="studio-compare"><div><span>BASELINE · ${esc(base.label)}</span><b class="${statusClass(baseline.decision)}">${baseline.decision}</b><small>Trust ${baseline.trust} · ${baseAgent.name}</small></div><div class="compare-arrow">→</div><div><span>LIVE VARIANT · ${esc(agent.name)}</span><b class="${statusClass(current.decision)}">${current.decision}</b><small>Trust ${current.trust} · ${s.env} · ${String(s.hour).padStart(2,'0')}:00</small></div></div><div class="studio-reasons"><div class="studio-reasons-head"><span>CONTEXT SIGNALS</span><span>LIVE RISK PROFILE</span></div><div class="signal-grid">${checks.map(([n,v])=>`<div class="signal"><span>${n}</span><div class="signal-track"><i style="width:${v}%"></i></div><b>${v}</b></div>`).join('')}</div><div class="studio-trigger">${current.reasons.slice(0,3).map(r=>`<span><i>+</i>${esc(r.label)}</span>`).join('')||'<span class="pass-trigger"><i>✓</i> No adverse context signals</span>'}</div></div><div class="curve-panel"><div class="curve-head"><div><span class="eyebrow">TRUST SENSITIVITY CURVE</span><small>Requested amount vs dynamic trust · same live context</small></div><span class="curve-legend"><i></i> TRUST SCORE</span></div>${studioCurve()}</div><div class="studio-commit"><span><i class="dot green"></i> Sandbox only · This simulation never executes the proposed action</span><button class="primary" id="send-variant">EVALUATE VARIANT IN CONTROL PLANE <span>→</span></button></div></div>`}
function studio(){const s=scenarios.find(x=>x.id===state.studioScenario)||scenarios[1],targets=[...new Set([state.studioTarget,'Internal finance API','Unknown refund API','Unverified vendor API','External webhook','Verified finance API','Agent runtime','External endpoint','Production identity service','Production database','Internal reporting API'])];return `<div class="page-head"><div><div class="eyebrow">DYNAMIC TRUST / INTERACTIVE SANDBOX</div><h1>Trust Simulator</h1><p>Change one action's context and see how the same authorization earns a different decision.</p></div><span class="live-pill"><i class="dot green"></i> WHAT-IF MODE · NO EXECUTION</span></div><div class="studio-hero"><div class="studio-hero-icon">◉</div><div><span class="eyebrow">THE AEGIS QUESTION</span><h2>What changed between <em>can</em> and <em>should</em>?</h2><p>Adjust the context. Watch trust recalculate against the baseline in real time.</p></div><div class="studio-hero-stamp">ACTION<br>≠<br>CONTEXT</div></div><div class="studio-layout"><section class="panel studio-controls"><div class="panel-title"><div><span class="step-no">01</span><h2>Change the context</h2></div><button class="text-button" id="studio-reset">RESET BASELINE ↺</button></div><label>BASE ACTION<select id="studio-scenario">${scenarios.filter(x=>x.id!=='safe').map(x=>`<option value="${x.id}" ${x.id===state.studioScenario?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><div class="studio-action-copy"><span>PROPOSED INTENT</span><b>${esc(s.action)}</b></div><label>AGENT IDENTITY<select id="studio-agent">${agents.map(x=>`<option value="${x.id}" ${x.id===state.studioAgent?'selected':''}>${esc(x.name)} · ${x.id}</option>`).join('')}</select></label><div class="context-presets"><button type="button" class="chip" data-studio-preset="routine">TRUSTED DAY CONTEXT</button><button type="button" class="chip" data-studio-preset="night">NIGHT BURST CONTEXT</button></div><div class="studio-control"><div><label for="studio-hour">REQUEST TIME</label><output id="time-output">${String(state.studioHour).padStart(2,'0')}:00</output></div><input type="range" min="0" max="23" step="1" value="${state.studioHour}" id="studio-hour" data-studio="hour"><div class="range-scale"><span>00:00</span><span>23:00</span></div></div><div class="studio-control"><div><label for="studio-frequency">ACTION BURST · PER 10 MIN</label><output id="frequency-output">${state.studioFrequency} actions</output></div><input type="range" min="1" max="30" step="1" value="${state.studioFrequency}" id="studio-frequency" data-studio="frequency"><div class="range-scale"><span>1 action</span><span>30 actions</span></div></div><div class="studio-control"><div><label for="studio-amount">REQUESTED AMOUNT</label><output id="amount-output">₹${Number(state.studioAmount).toLocaleString('en-IN')}</output></div><input type="range" min="0" max="150000" step="1000" value="${state.studioAmount}" id="studio-amount" data-studio="amount"><div class="range-scale"><span>₹0</span><span>₹1,50,000</span></div></div><div class="studio-select-grid"><label>ENVIRONMENT<select id="studio-env">${['Production','Staging','Development'].map(x=>`<option ${state.studioEnv===x?'selected':''}>${x}</option>`).join('')}</select></label><label>DESTINATION<select id="studio-target">${targets.map(x=>`<option ${state.studioTarget===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><label class="reversible-toggle"><input type="checkbox" id="studio-reversible" ${state.studioReversible?'checked':''}><span class="toggle-ui"></span><span><b>REVERSIBLE ACTION</b><small>Can the action be reliably undone?</small></span></label></section><section class="panel studio-output"><div class="panel-title"><div><span class="step-no">02</span><h2>Live decision twin</h2></div><span class="tag">DETERMINISTIC · EXPLAINABLE</span></div><div id="studio-results">${studioResults()}</div></section></div><div class="studio-note"><b>How to demo:</b> Keep the same refund action, change the agent or operating context, and compare the resulting trust path. Results use the local rules engine; no real payment or service is connected.</div>`}
function attacks(){const entries=scenarios.map(s=>({scenario:s,agent:agents.find(a=>a.id===s.agent)}));const counts={ALL:entries.length,CRITICAL:entries.filter(x=>evaluate(x.scenario,x.agent).critical).length,REVIEW:entries.filter(x=>evaluate(x.scenario,x.agent).decision==='REVIEW').length,SAFE:entries.filter(x=>evaluate(x.scenario,x.agent).decision==='ALLOW').length};const visible=entries.filter(x=>state.attackFilter==='ALL'||(state.attackFilter==='CRITICAL'&&evaluate(x.scenario,x.agent).critical)||(state.attackFilter==='REVIEW'&&evaluate(x.scenario,x.agent).decision==='REVIEW')||(state.attackFilter==='SAFE'&&evaluate(x.scenario,x.agent).decision==='ALLOW'));return `<div class="page-head"><div><div class="eyebrow">DETERMINISTIC SECURITY FILTER / LOCAL SIMULATION</div><h1>Attack Lab</h1><p>Threat scenarios run through the same local policy engine and generate traceable decisions.</p></div><span class="live-pill"><i class="dot green"></i> ${scenarios.length} SCENARIOS READY</span></div><div class="attack-intro"><div><span class="eyebrow">STAGE 1 · INSTANT INTERCEPTION</span><h2>Catch the threat before semantic reasoning.</h2><p>Regex-based deterministic filters detect known patterns. Critical matches are blocked before a tool call.</p></div><div class="saving"><b>${counts.CRITICAL}</b><span>CRITICAL ATTACKS<br>INTERCEPTED LOCALLY</span></div></div><div class="attack-summary"><div><b>10</b><span>THREAT & SAFETY CASES</span></div><div><b>${counts.CRITICAL}</b><span>CRITICAL OVERRIDES</span></div><div><b>${counts.REVIEW}</b><span>HUMAN REVIEWS</span></div><div><b>${counts.SAFE}</b><span>SAFE PATHS</span></div></div><div class="attack-toolbar"><div class="attack-filters">${Object.entries(counts).map(([k,v])=>`<button class="filter ${state.attackFilter===k?'active':''}" data-attack-filter="${k}">${k} <span>${v}</span></button>`).join('')}</div><span>DETERMINISTIC SECURITY FILTER · OFFLINE</span></div><div class="attack-grid">${visible.map(({scenario:s,agent},i)=>{const result=evaluate(s,agent);const label=result.decision==='ALLOW'?'ALLOW':result.decision==='REVIEW'?'HUMAN REVIEW':'BLOCK';return `<article class="panel attack-card ${result.critical?'critical-card':''}"><div class="attack-top"><span class="attack-index">${String(i+1).padStart(2,'0')} / ${esc(s.family||'SAFETY CHECK')}</span><span class="decision-pill ${statusClass(result.decision)}">${label}</span></div><h2>${esc(s.label)}</h2><p>${esc(s.action)}</p><div class="attack-evidence"><div><span class="evidence-label">DETECTED EVIDENCE</span><b>${result.flags.length?result.flags.map(esc).join(' · '):result.reasons.slice(0,2).map(x=>esc(x.label)).join(' · ')||'No adverse signals'}</b></div><div class="attack-card-meta"><span>TRUST <b>${result.trust}</b></span><span>BLAST <b>${result.blast}</b></span><span>LATENCY <b>${result.latency}ms</b></span></div></div><div class="attack-card-foot"><small>${result.critical?'CRITICAL OVERRIDE · TOKEN SAVING ACTIVE':s.id==='safe'?'NO EXTERNAL ACTION · READ ONLY':'SIMULATED · NO PAYLOAD EXECUTED'}</small><button class="outline" data-scenario="${s.id}">RUN SCENARIO <span>→</span></button></div></article>`}).join('')||'<div class="panel no-attacks">No scenarios in this filter.</div>'}</div><div class="notice"><span>ⓘ</span><p><b>Simulation only.</b> AEGIS evaluates proposed actions and records the outcome. No payload is executed or sent to an external system.</p></div>`}
function auditRows(items){return `<div class="table-wrap"><table><thead><tr><th>EVENT</th><th>TIME</th><th>AGENT</th><th>PROPOSED ACTION</th><th>TRUST</th><th>BLAST</th><th>DECISION</th><th>REVIEWER</th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td class="mono">${esc(x.id)}</td><td>${esc(x.time)}</td><td class="mono">${esc(x.agent)}</td><td class="action-cell">${esc(x.action)}</td><td><b>${x.trust}</b></td><td>${x.blast}</td><td><span class="decision-pill ${statusClass(x.decision)}">${x.decision}</span></td><td>${esc(x.reviewer||'—')}</td></tr>`).join(''):`<tr><td colspan="8" class="no-data">NO GOVERNANCE EVENTS FOUND</td></tr>`}</tbody></table></div>`}
function auditPage(){let rows=state.audit.filter(x=>(state.filter==='ALL'||x.decision===state.filter)&&(!state.search||`${x.id} ${x.agent} ${x.action}`.toLowerCase().includes(state.search.toLowerCase())));return `<div class="page-head"><div><div class="eyebrow">IMMUTABLE GOVERNANCE RECORD / LOCAL</div><h1>Audit Trail</h1><p>Every evaluation creates a traceable governance event.</p></div><button class="outline" id="export">EXPORT CSV ↓</button></div><div class="panel audit-panel"><div class="audit-tools"><label class="search">⌕ <input id="search" placeholder="Search agent, action, event..." value="${esc(state.search)}"></label><div class="filters">${['ALL','ALLOW','REVIEW','BLOCK'].map(x=>`<button class="filter ${state.filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><span class="record-count">${rows.length} EVENTS</span></div>${auditRows(rows)}</div><div class="audit-footnote"><span class="dot green"></span> Locally persisted in this browser <span>·</span> Audit evidence is demonstrative, not tamper-proof</div>`}
const archInfo={human:['Human operator','Trust 100 · dual control','Approves exceptional actions and owns final human authorization.'],planner:['Planner agent','Trust 92 · scoped delegation','Produces a proposal and passes source identity along the trust chain.'],finance:['Finance agent',`${state.agent.trust} trust · AGT-FIN-042`,'Carries the business intent, permitted amount range, and behavioural baseline.'],gate:['AEGIS decision gate','Intercept · before tool execution','Evaluates identity, guardrails, behaviour, impact, reversibility, and remaining risk budget.'],policy:['Policy + risk engine','Local deterministic provider','Applies explainable rules and critical overrides without relying on a network model.'],adapter:['Tool adapter','Quarantined · simulated','Represents a controlled boundary; this prototype has no connected executor.'],api:['Protected API','Unreachable in demo','A downstream service is only shown as a projected target, never called.'],audit:['Audit + evidence','Locally persisted · illustrative','Records decision rationale, reviewer action, and projected blast radius in browser storage.'],map:['Counterfactual model','Projected impact · simulated','Estimates affected systems and reversibility for the proposal; it is not an observed outcome.']};
function architecture(){let attack=state.archMode==='attack',lineage=state.archMode==='lineage';let names=[['human',76,'HUMAN','OPERATOR'],['planner',222,'PLANNER','AGENT'],['finance',368,'FINANCE','AGENT'],['gate',514,'AEGIS','GATEWAY'],['policy',660,'POLICY','ENGINE'],['adapter',806,'TOOL','ADAPTER'],['api',952,'PROTECTED','API']];let node=(id,x,l1,l2)=>`<g class="arch-svg-node ${state.archNode===id?'selected':''} ${attack&&['planner','gate'].includes(id)?'threatened':''}" data-arch-node="${id}" role="button" tabindex="0" aria-label="Inspect ${l1} ${l2}"><circle class="node-halo" cx="${x}" cy="121" r="53"/><rect x="${x-53}" y="68" width="106" height="106" rx="11"/><circle class="node-glyph" cx="${x}" cy="105" r="15"/><text class="node-mark" x="${x}" y="111">${{human:'H',planner:'P',finance:'F',gate:'A',policy:'Σ',adapter:'T',api:'◈'}[id]}</text><text class="node-label" x="${x}" y="145">${l1}</text><text class="node-sub" x="${x}" y="159">${l2}</text></g>`;let desc=archInfo[state.archNode]||archInfo.gate;return `<div class="page-head"><div><div class="eyebrow">SYSTEM DESIGN / INTERACTIVE TRUST GRAPH</div><h1>Architecture</h1><p>Explore identity, policy and tool boundaries across the simulated governance path.</p></div><span class="live-pill"><i class="dot green"></i> LOCAL FALLBACK ACTIVE</span></div><section class="panel architecture-panel"><div class="arch-title"><div><span class="eyebrow">PRE-EXECUTION CONTROL FLOW</span><span class="arch-subtitle">SEVEN CHECKPOINTS · ONE HUMAN AUTHORITY</span></div><span class="tag">NO CONNECTED EXECUTORS</span></div><div class="arch-controls"><div class="arch-modes">${[['normal','TRUST PATH'],['attack','INJECTION PATH'],['lineage','DATA LINEAGE']].map(([id,t])=>`<button class="filter ${state.archMode===id?'active':''}" data-arch-mode="${id}">${t}</button>`).join('')}</div><button class="primary" id="simulate-architecture">${attack?'RESET TO TRUST PATH':'SIMULATE INTERCEPT'} <span>↗</span></button></div><div class="architecture-visual ${attack?'mode-attack':''} ${lineage?'mode-lineage':''}"><svg class="architecture-svg" viewBox="0 0 1028 490" role="img" aria-labelledby="arch-svg-title arch-svg-desc"><title id="arch-svg-title">AEGIS interactive control plane architecture</title><desc id="arch-svg-desc">Seven checkpoint trust chain from human operator through agents and the AEGIS decision gate to a simulated protected API, with evidence and counterfactual branches.</desc><defs><linearGradient id="trustFlow"><stop stop-color="var(--teal)"/><stop offset=".55" stop-color="var(--teal2)"/><stop offset="1" stop-color="#728ca0"/></linearGradient><linearGradient id="attackFlow"><stop stop-color="#f4bb64"/><stop offset=".55" stop-color="#f0717d"/><stop offset="1" stop-color="#f0717d"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter><marker id="arrowCyan" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="var(--teal)"/></marker><marker id="arrowRed" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#f0717d"/></marker></defs><g class="grid-dots">${Array.from({length:32},(_,i)=>`<circle cx="${25+i%8*140}" cy="${20+Math.floor(i/8)*118}" r="1"/>`).join('')}</g><text class="svg-label" x="28" y="36">IDENTITY &amp; INTENT</text><text class="svg-label" x="430" y="36">PRE-EXECUTION GOVERNANCE</text><text class="svg-label" x="844" y="36">SIMULATED EXECUTION BOUNDARY</text><path class="trust-wire ${attack?'dimmed':''}" marker-end="url(#arrowCyan)" d="M129 121 H169 M275 121 H315 M421 121 H461 M567 121 H607 M713 121 H753 M859 121 H899"/><path class="attack-wire" marker-end="url(#arrowRed)" d="M275 121 H474"/><path class="branch-wire ${lineage?'lit':''}" d="M514 174 V260 H343 V297 M660 174 V260 H684 V297"/><path class="audit-wire" d="M343 349 H514 M684 349 H514 V174"/><text class="flow-note" x="514" y="221">REVIEW / BLOCK PATH</text><text class="flow-note" x="514" y="281">EVIDENCE &amp; SIMULATED CONSEQUENCE</text>${names.map(([id,x,a,b])=>node(id,x,a,b)).join('')}<g class="arch-svg-node branch-node ${state.archNode==='audit'?'selected':''}" data-arch-node="audit" role="button" tabindex="0" aria-label="Inspect audit evidence"><rect x="271" y="297" width="144" height="52" rx="8"/><text class="branch-title" x="343" y="320">AUDIT + EVIDENCE</text><text class="branch-sub" x="343" y="337">REVIEWER · RATIONALE · TRACE</text></g><g class="arch-svg-node branch-node ${state.archNode==='map'?'selected':''}" data-arch-node="map" role="button" tabindex="0" aria-label="Inspect counterfactual model"><rect x="612" y="297" width="144" height="52" rx="8"/><text class="branch-title" x="684" y="320">COUNTERFACTUAL</text><text class="branch-sub" x="684" y="337">PROJECTED IMPACT · NEVER ACTUAL</text></g><g class="gate-burst ${attack?'burst-on':''}" transform="translate(514 121)"><circle r="68"/><circle r="77"/></g><g class="blocked-stamp ${attack?'show':''}" transform="translate(514 211)"><rect x="-52" y="-12" width="104" height="24" rx="3"/><text x="0" y="4">INTERCEPTED</text></g><text class="svg-footnote" x="28" y="449">TRUSTED REQUEST</text><line class="legend-good" x1="125" y1="446" x2="165" y2="446"/><text class="svg-footnote" x="185" y="449">POLICY-GATED DATA FLOW</text><line class="legend-branch" x1="340" y1="446" x2="380" y2="446"/><text class="svg-footnote" x="400" y="449">BLOCKED ADVERSARIAL PATH</text><line class="legend-threat" x1="562" y1="446" x2="602" y2="446"/><text class="svg-footnote" x="730" y="449">SIMULATED · NO TOOL CALLED</text></svg></div><div class="arch-inspector"><div class="inspector-icon">${state.archNode==='gate'?'◇':state.archNode==='policy'?'Σ':state.archNode==='audit'?'▤':state.archNode==='map'?'◎':'◈'}</div><div class="inspector-copy"><span class="eyebrow">SELECTED CHECKPOINT · ${state.archNode.toUpperCase()}</span><h2>${esc(desc[0])}</h2><p>${esc(desc[2])}</p></div><div class="inspector-metric"><span>IDENTITY / CONTROL STATE</span><b>${esc(desc[1])}</b></div></div></section>${renderReceiptLedger(state.audit,state.receiptIntegrity,state.receiptExpanded)}<div class="arch-bottom">${qualcommPanel()}<section class="panel"><span class="eyebrow">DECISION PRIORITY</span><ol><li>Critical security violation</li><li>Forbidden action / authorization</li><li>Trust-chain violation and budget breach</li><li>Dynamic trust thresholds</li><li>Record decision, rationale and reviewer</li></ol></section></div>`}
function qualcommPanel(){return `<section class="panel qai-panel"><div class="qai-head"><div><span class="eyebrow">OPTIONAL SERVER-SIDE AI EXPLANATION</span><h2>Qualcomm Cloud AI Playground</h2><p>AEGIS sends the evaluated scenario to its local backend; the backend calls your configured Qualcomm-compatible endpoint.</p></div><span class="qai-status"><i class="dot amber"></i>${esc(state.qualcommStatus)}</span></div><div class="qai-guardrail"><b>BACKEND-MANAGED CREDENTIALS</b><span>Set QAI_API_KEY, QAI_MODEL, and QAI_ENDPOINT in the server environment. The browser never receives or stores the provider key. Use a trusted endpoint and synthetic demo data.</span></div><div class="qai-actions"><button class="outline" id="qai-test">TEST BACKEND CONNECTION</button><a href="https://www.qualcomm.com/developer/software/qualcomm-ai-inference-suite" target="_blank" rel="noopener">PLAYGROUND SETUP ↗</a></div></section>`}
function decisionExplainer(e){return `<section class="panel decision-explainer"><div class="explainer-copy"><span class="eyebrow">DECISION, IN PLAIN LANGUAGE</span><h2>Explain the current decision</h2><p>Get a concise operator explanation for this evaluated action. The deterministic AEGIS policy remains the authority.</p><div class="explainer-status"><i class="dot ${state.qualcommStatus==='BACKEND READY'?'green':'amber'}"></i>${esc(state.qualcommStatus)} · SERVER CONFIGURATION</div></div><div class="explainer-result">${state.qualcommOutput?`<p>${esc(state.qualcommOutput)}</p>`:`<span>${e?'Ready to explain the current '+e.decision+' decision.':'Evaluate an action to enable its explanation.'}</span>`}<button class="primary" id="qai-explain" ${e?'':'disabled'}>${state.qualcommOutput==='Generating explanation…'?'GENERATING…':'EXPLAIN CURRENT DECISION'} <span>→</span></button></div></section>`}
async function testBackendConnection(){state.qualcommStatus='TESTING BACKEND';render();try{const response=await fetch('/api/qai/test',{method:'POST'});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Backend returned HTTP ${response.status}.`);state.qualcommStatus='BACKEND READY';state.qualcommOutput='Connection verified. Use Explain current decision on the Control Plane.'}catch(error){state.qualcommStatus=error.message.includes('not configured')?'BACKEND NOT CONFIGURED':'BACKEND ERROR';state.qualcommOutput=error.message}render()}
async function explainWithQualcomm(){const evaluation=state.evaluation||evaluate(state.action,state.agent);if(evaluation.error){state.qualcommOutput=evaluation.error;render();return}const reasons=evaluation.reasons?.slice(0,4).map(x=>`${x.category}: ${x.label}`).join('; ')||'No adverse signals';state.qualcommOutput='Generating explanation…';render();try{const response=await fetch('/api/qai/explain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agent:state.agent.name,action:state.action.action,environment:state.action.env,decision:evaluation.decision,trust:evaluation.trust,blastRadius:evaluation.blast,signals:reasons})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Backend returned HTTP ${response.status}.`);state.qualcommStatus='BACKEND READY';state.qualcommOutput=data.explanation}catch(error){state.qualcommStatus=error.message.includes('not configured')?'BACKEND NOT CONFIGURED':'BACKEND ERROR';state.qualcommOutput=error.message}render()}
function mapModal(){const e=state.evaluation||evaluate(state.action,state.agent),dna=e.actionDNA||{},amount=dna.amount||Number(state.action.amount)||0,financial=amount>0,steps=[{title:'Agent dispatch',state:'INITIATED',icon:'◉',body:`${esc(state.agent.name)} requested: ${esc(state.action.action)}`,impact:'The request leaves the agent runtime with its original context.'},{title:'AEGIS gateway',state:e.decision==='ALLOW'?'AUTHORIZED':'INTERCEPTED',icon:'⬡',body:e.decision==='ALLOW'?'Policy checks passed for this context.':'Dynamic context checks raised a governance decision before the external target.',impact:e.decision==='ALLOW'?'The proposal clears policy in this simulation.':`${e.decision} is the current simulated decision; this map explores the counterfactual route.`},{title:'Simulated target',state:'PROJECTED',icon:'⇢',body:`Would reach ${esc(dna.target||state.action.target||'External service')} if the gateway did not intercept it.`,impact:financial?`Projected transfer exposure: ₹${amount.toLocaleString('en-IN')}. No transfer occurred.`:'Projected downstream access or data exposure depends on the target; no request was sent.'},{title:'Downstream impact',state:e.blast>=70?'HIGH RISK':'CONTAINED',icon:'◎',body:'Potential consequence is estimated from the scenario’s blast radius and action context.',impact:`Blast radius score ${e.blast}/100 · Reversibility: ${esc(dna.reversibility||'Unknown')}. This is a deterministic prototype estimate, not a recovery guarantee.`}],active=steps[state.mapHop||0]||steps[0],decision=e.decision||'REVIEW';return `<div class="modal-backdrop" id="backdrop"><section class="map-modal consequence-modal" role="dialog" aria-modal="true" aria-labelledby="map-title"><button class="modal-close" id="closeMap" aria-label="Close">×</button><span class="eyebrow">COUNTERFACTUAL SAFETY ENGINE · SIMULATED PROJECTION</span><h2 id="map-title">What if AEGIS did not intercept?</h2><p>Explore the projected route and select a hop to inspect its consequence.</p><div class="prototype-banner"><b>PROTOTYPE SIMULATION NOTICE</b><span>All consequences are simulated projections. No real-world actions were executed.</span></div><div class="projection-heading"><div><span class="eyebrow">PROJECTED EXECUTION TOPOLOGY</span><strong>${decision==='ALLOW'?'SAFE FLOW AUTHORIZED':'INTERCEPTED · COUNTERFACTUAL CONTINUED'}</strong></div><span class="blast-score"><b>${e.blast}</b><small>/ 100<br>BLAST RADIUS</small></span></div><div class="map-scene consequence-scene"><div class="route-line" aria-hidden="true"><i></i></div>${steps.map((step,i)=>`<button class="route-node ${i===state.mapHop?'selected':''} ${i===1&&decision!=='ALLOW'?'intercepted':''} ${i>1&&decision!=='ALLOW'?'counterfactual':''}" data-map-hop="${i}" aria-pressed="${i===(state.mapHop||0)}"><span>${step.icon}</span><b>0${i+1} · ${step.title}</b><small>${step.state}</small></button>`).join('')}</div><div class="hop-detail"><div class="hop-detail-title"><span>0${(state.mapHop||0)+1}</span><div><b>${active.title}</b><small>${active.state}</small></div></div><p>${active.body}</p><div class="projected-impact">${active.impact}</div></div><div class="exposure-row"><div><span>PROJECTED EXPOSURE</span><b>${financial?`₹${amount.toLocaleString('en-IN')} potential financial impact`:'Potential downstream access or data impact'}</b></div><div><span>REVERSIBILITY</span><b>${esc(dna.reversibility||'Context dependent')}</b></div></div><div class="map-disclaimer"><b>SIMULATED COUNTERFACTUAL</b><span>Projected consequence only · No external action performed</span></div></section></div>`}
function bind(){document.querySelectorAll('a[href^="#"]').forEach(el=>el.onclick=()=>{state.page=el.hash.slice(1);});$('#login')?.addEventListener('submit',ev=>{ev.preventDefault();state.logged=true;sessionStorage.aegisLogin='1';render();});$('#logout')?.addEventListener('click',()=>{state.logged=false;sessionStorage.removeItem('aegisLogin');render();});$('#theme')?.addEventListener('click',()=>{state.dark=!state.dark;localStorage.aegisTheme=state.dark?'dark':'light';render();});$('#agent')?.addEventListener('change',ev=>{state.agent=agents.find(x=>x.id===ev.target.value);render();});$('#environment')?.addEventListener('change',ev=>state.action.env=ev.target.value);$('#action')?.addEventListener('input',ev=>state.action.action=ev.target.value);document.querySelectorAll('[data-scenario]').forEach(el=>el.addEventListener('click',()=>{let s=scenarios.find(x=>x.id===el.dataset.scenario);state.action={...s,timeLabel:`${String(s.hour).padStart(2,'0')}:47`};state.agent=agents.find(x=>x.id===s.agent);state.evaluation=null;state.qualcommOutput='';state.showWhy=false;if(state.page==='attacks'){state.page='overview';location.hash='overview';}render();if(el.closest('.attack-card'))evaluateAction();}));document.querySelectorAll('[data-attack-filter]').forEach(el=>el.addEventListener('click',()=>{state.attackFilter=el.dataset.attackFilter;render();}));document.querySelectorAll('[data-arch-mode]').forEach(el=>el.addEventListener('click',()=>{state.archMode=el.dataset.archMode;state.archNode=state.archMode==='attack'?'gate':state.archMode==='lineage'?'audit':'human';render();}));document.querySelectorAll('[data-arch-node]').forEach(el=>{el.addEventListener('click',()=>{state.archNode=el.dataset.archNode;render();});el.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();state.archNode=el.dataset.archNode;render();}});});$('#simulate-architecture')?.addEventListener('click',()=>{state.archMode=state.archMode==='attack'?'normal':'attack';state.archNode=state.archMode==='attack'?'gate':'human';render();});$('#evaluate')?.addEventListener('click',evaluateAction);$('#why')?.addEventListener('click',()=>{state.showWhy=!state.showWhy;render();});['map','map2'].forEach(id=>$('#'+id)?.addEventListener('click',()=>{state.showMap=true;render();}));document.querySelectorAll('[data-map-hop]').forEach(el=>el.addEventListener('click',()=>{state.mapHop=Number(el.dataset.mapHop);render();}));$('#closeMap')?.addEventListener('click',()=>{state.showMap=false;render();});$('#backdrop')?.addEventListener('click',ev=>{if(ev.target.id==='backdrop'){state.showMap=false;render();}});$('#approve')?.addEventListener('click',()=>resolve('ALLOW','R. Iyer'));$('#reject')?.addEventListener('click',()=>resolve('BLOCK','R. Iyer'));$('#sanitize')?.addEventListener('click',()=>{state.action={...scenarios[0]};state.agent=agents[0];state.evaluation=null;state.showWhy=false;render();notify('Payload sanitized. Review the safe report before evaluating.');});$('#passport')?.addEventListener('click',()=>notify(`${state.agent.id} · ${state.agent.permissions.join(' / ')}`));$('#search')?.addEventListener('input',ev=>{state.search=ev.target.value;let pos=ev.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{state.filter=el.dataset.filter;render();});$('#export')?.addEventListener('click',exportCsv);$('#qai-explain')?.addEventListener('click',explainWithQualcomm);$('#qai-test')?.addEventListener('click',testBackendConnection);$('#mobile-menu')?.addEventListener('click',()=>{const shell=$('.app-shell'),sidebar=$('.sidebar'),menu=$('#mobile-menu'),mobile=window.matchMedia('(max-width:800px)').matches;if(mobile){shell.classList.remove('sidebar-collapsed');sidebar.classList.toggle('mobile-open');const open=sidebar.classList.contains('mobile-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';}else{state.sidebarCollapsed=!state.sidebarCollapsed;localStorage.aegisSidebarCollapsed=state.sidebarCollapsed?'1':'0';shell.classList.toggle('sidebar-collapsed',state.sidebarCollapsed);const open=!state.sidebarCollapsed;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';}});}
function evaluateAction(){let text=$('#action')?.value;if(text!==undefined)state.action.action=text;let env=$('#environment')?.value;if(env)state.action.env=env;if(!state.action.action?.trim()){notify('ACTION INPUT REQUIRED');return;}state.evaluation=evaluate(state.action,state.agent);state.qualcommOutput='';state.showWhy=true;let e=state.evaluation;state.audit.unshift({id:`EVT-${2042+state.audit.length}`,time:new Date().toLocaleTimeString('en-GB'),agent:state.agent.id,action:state.action.action.slice(0,90),trust:e.trust,blast:e.blast,decision:e.decision,reviewer:'—'});save();render();sealReceipts();}
function resolve(decision,reviewer){let row=state.audit[0];if(row){row.decision=decision;row.reviewer=reviewer;delete row.receiptHash;delete row.previousHash;}save();state.evaluation={...state.evaluation,decision};state.showWhy=false;render();sealReceipts();notify(decision==='BLOCK'?'Action rejected and recorded.':'Human approval recorded.');}
function notify(s){state.toast=s;render();setTimeout(()=>{state.toast='';render();},2800)}
function exportCsv(){let rows=[['Event','Time','Agent','Action','Trust','Blast','Decision','Reviewer'],...state.audit.map(x=>[x.id,x.time,x.agent,x.action,x.trust,x.blast,x.decision,x.reviewer])];let csv=rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='aegis-audit.csv';a.click();URL.revokeObjectURL(a.href);}
function refreshStudio(){let hour=$('#time-output'),freq=$('#frequency-output'),amount=$('#amount-output'),copy=$('.studio-action-copy b');if(hour)hour.textContent=`${String(state.studioHour).padStart(2,'0')}:00`;if(freq)freq.textContent=`${state.studioFrequency} actions`;if(amount)amount.textContent=`₹${Number(state.studioAmount).toLocaleString('en-IN')}`;let s=scenarios.find(x=>x.id===state.studioScenario);if(copy&&s)copy.textContent=s.action;let results=$('#studio-results');if(results){results.innerHTML=studioResults();}}
function resetStudio(id=state.studioScenario){let s=scenarios.find(x=>x.id===id)||scenarios[1];state.studioScenario=s.id;state.studioAgent=s.agent;state.studioEnv=s.env;state.studioHour=s.hour;state.studioFrequency=s.frequency;state.studioAmount=s.amount;state.studioTarget=s.target;state.studioReversible=s.reversible;render();}
function commitStudioVariant(){let action=studioContext();state.agent=agents.find(x=>x.id===state.studioAgent)||agents[0];state.action=action;state.evaluation=evaluate(action,state.agent);state.qualcommOutput='';state.showWhy=true;state.audit.unshift({id:`EVT-${Date.now()}`,time:new Date().toLocaleTimeString('en-GB'),agent:state.agent.id,action:action.action.slice(0,90),trust:state.evaluation.trust,blast:state.evaluation.blast,decision:state.evaluation.decision,reviewer:'—'});save();state.page='overview';location.hash='overview';render();sealReceipts();}
document.addEventListener('input',ev=>{const el=ev.target;if(!el.matches('[data-studio]'))return;state[`studio${el.dataset.studio[0].toUpperCase()}${el.dataset.studio.slice(1)}`]=Number(el.value);refreshStudio();});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='studio-scenario'){resetStudio(el.value);return;}if(el.id==='studio-agent')state.studioAgent=el.value;if(el.id==='studio-env')state.studioEnv=el.value;if(el.id==='studio-target')state.studioTarget=el.value;if(el.id==='studio-reversible')state.studioReversible=el.checked;if(['studio-agent','studio-env','studio-target','studio-reversible'].includes(el.id))refreshStudio();});
document.addEventListener('click',ev=>{if(ev.target.closest('#studio-reset'))resetStudio();if(ev.target.closest('#send-variant'))commitStudioVariant();const preset=ev.target.closest('[data-studio-preset]');if(preset){const trusted=preset.dataset.studioPreset==='routine';Object.assign(state,{studioAgent:trusted?'AGT-FIN-008':'AGT-FIN-042',studioEnv:trusted?'Staging':'Production',studioHour:trusted?14:2,studioFrequency:trusted?2:17,studioAmount:48000,studioTarget:trusted?'Verified finance API':'Unknown refund API',studioReversible:trusted});$('#studio-agent').value=state.studioAgent;$('#studio-env').value=state.studioEnv;$('#studio-target').value=state.studioTarget;$('#studio-hour').value=state.studioHour;$('#studio-frequency').value=state.studioFrequency;$('#studio-amount').value=state.studioAmount;$('#studio-reversible').checked=state.studioReversible;refreshStudio();}if(ev.target.closest('#verify-chain'))verifyReceiptsNow();const receipt=ev.target.closest('[data-receipt]');if(receipt){state.receiptExpanded=state.receiptExpanded===receipt.dataset.receipt?null:receipt.dataset.receipt;render();}});
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview';render();});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.showMap){state.showMap=false;render();}});render();sealReceipts();loadProviderStatus();
